INSERT INTO `rca_case` VALUES ('RCA-MINI-308207','ทบทวนสาเหตุเชิงระบบ Mini RCA','mini','2026-08-18 08:01:47','2026-08-18 08:01:47','เมื่อเวลา 13.00 น. ได้มีผุ้ป่วยมานั่งรอรับบริการในช่วงพักเที่ยง พอถึงเวลา13.00 น. ผู้ป่วยมายื่นบัตรใบนำทาง ปรากฎว่า เป็นยื่นนวดแผนไทย 1 ราย และนวดแผนไทย+ฝังเข็มอีก 1  ราย ทำให้ผู้ป่วยเสียเวลาในการนั่งรอรับบริการ เนื่องจากไม่มีป้ายแผนกชัดเจน',204,'2026-08-18 01:05:08','2026-08-18 01:05:08'),('RCA-MINI-516876','HR/03 เจ้าหน้าที่ไม่ปฏิบัติตามกฎเกณฑ์ ข้อตกลง หรือระเบียบที่กำหนด','mini','2026-08-09 15:31:56','2026-06-11 00:00:00','พบแมสในถังผ้าทั่วไป',163,'2026-08-09 08:31:56','2026-08-09 08:31:56'),('RCA-MINI-571777','PT/21 การวินิจฉัยโรคผิดพลาด/ไม่ชัดเจน/ล่าช้า','mini','2026-08-09 15:32:51','2026-05-22 00:00:00','HN570001260 เคสแรกรับ dx: cellulitis with septic shock ลักษณะแผลติดเชื้อรุนแรงตั้งแต่แรกรับ ร่วมกับ levophed rate 57 ตั้งแต่ก่อน admit\r\nควรได้ consult ขอ refer ตั้งแต่ ER\r\nหลังเข้าหอผู้ป่วยไม่ถึง4ชม. เหนื่อยขึ้น ซึมลง levophed rate72 -> dx: NF with septic shock with RS failure -> refer เวรบ่าย',163,'2026-08-09 08:32:51','2026-08-09 08:32:51');
