INSERT INTO `rca_incident_item` VALUES (1,'RCA-MINI-516876',13475,13438,'HR/03 เจ้าหน้าที่ไม่ปฏิบัติตามกฎเกณฑ์ ข้อตกลง หรือระเบียบที่กำหนด',NULL,'C','17','พบแมสในถังผ้าทั่วไป',0,'2026-08-09 08:31:56'),(2,'RCA-MINI-571777',13375,13388,'PT/21 การวินิจฉัยโรคผิดพลาด/ไม่ชัดเจน/ล่าช้า',NULL,'C','14','HN570001260 เคสแรกรับ dx: cellulitis with septic shock ลักษณะแผลติดเชื้อรุนแรงตั้งแต่แรกรับ ร่วมกับ levophed rate 57 ตั้งแต่ก่อน admit\r\nควรได้ consult ขอ refer ตั้งแต่ ER\r\nหลังเข้าหอผู้ป่วยไม่ถึง4ชม. เหนื่อยขึ้น ซึมลง levophed rate72 -> dx: NF with septic shock with RS failure -> refer เวรบ่าย',0,'2026-08-09 08:32:51'),(3,'RCA-MINI-308207',12150,12141,'ทบทวนสาเหตุเชิงระบบ Mini RCA',NULL,'2','46','เมื่อเวลา 13.00 น. ได้มีผุ้ป่วยมานั่งรอรับบริการในช่วงพักเที่ยง พอถึงเวลา13.00 น. ผู้ป่วยมายื่นบัตรใบนำทาง ปรากฎว่า เป็นยื่นนวดแผนไทย 1 ราย และนวดแผนไทย+ฝังเข็มอีก 1  ราย ทำให้ผู้ป่วยเสียเวลาในการนั่งรอรับบริการ เนื่องจากไม่มีป้ายแผนกชัดเจน',0,'2026-08-18 01:05:08');
/*!40000 ALTER TABLE `rca_incident_item` ENABLE KEYS */;
UNLOCK TABLES;

