INSERT INTO `risk` VALUES (8747,'2020-06-12','08:12:00',1,51,'1',NULL,6,'B',410,'ผู้ช่วยเหลือคนไข้ไม่ปฏิบัติตามเเนวทางการส่งตรวจผลเลือดที่ว่างไว้ คือ ไม่ได้นำเลือดพร้อมสมุดผู็ส่งผู้รับ ทำให้ตัวอย่างผลเลือดส่งตรวจหายไม่ทราบสาเหตุ ผป.ต้องถูกเจาะเลือดใหม่เเละผลการชันสูตรล่าช้า',NULL,'ผู้ป่วย,โรงพยาบาล,อื่นๆ','ได้','1.เเจ้งหัวหน้าเวร 2.รายงานหัวหน้สหอผู้ป่วย 3.เจาะเลือดส่งตรวจใหม่','',8,'ตรวจสอบ',307,'2',307,'2020-06-13 02:19:19','2020-06-22 02:06:58'),(8748,'2020-06-13','02:00:00',3,51,'1',NULL,2,'1',98,'ญาติผู้ป่วยสูบหรี่บริเวณระเบียงหอผู้ป่วยฝั่งหญิง',NULL,'ผู้ป่วย,ญาติ,เจ้าหน้าที่,โรงพยาบาล','ได้','เเจ้งเเก่ญาิติผู้ป่วยถึงข้อห้ามของการสูบบหรี่ในโรงพยาบาล','',1,'ตรวจสอบ',307,'2',307,'2020-06-13 02:26:17','2020-06-12 19:35:10'),(8749,'2020-06-14','16:57:35',1,23,'1',NULL,6,'B',292,'แพทย์เวรอีอาร์ เขียนรายการเอกซเรย์และสั่งรายการเอกซเรย์ผู้ป่วยผิดข้าง ผู้ป่วยเจ็บเข่าขวา แต่แพทย์เวรสั่งเข่าซ้าย',NULL,'ผู้ป่วย','ได้','เจ้าหน้าที่เอกซเรย์สอบถามผู้ป่วยว่าเจ็บเข่าข้างไหน แล้วทำการเอกซเรย์ข้างที่ถูกต้อง แล้วรายงานแพทย์ให้ทราบว่าแพทย์สั่งรายการผิด','',8,'ตรวจสอบ',253,'7',253,'2020-06-14 16:59:49','2020-06-14 10:00:02'),(8750,'2020-05-25','14:24:40',1,35,'2',21,2,'2',136,'ฝนตก ไฟดับ เครื่องสำรองไฟไม่ทำงาน ทำให้ระบบอินเตอร์เนตใช้งานไม่ได้',NULL,'โรงพยาบาล','ไม่ได้','','',8,'ตรวจสอบ',161,'20',161,'2020-06-15 10:31:17','2020-06-15 04:14:03'),(8751,'2020-06-01','08:30:20',1,35,'1',NULL,2,'2',136,'โปรแกรมhos xp ใช้งานไม่ได้ เพราะไฟตก ระบบสำรองไฟไม่ทำงาน ทำให้ระบบ network มีปัญหา',NULL,'โรงพยาบาล','ไม่ได้','ทำเรื่องจัดซื้อเครื่องสำรองไฟแต่เนื่องจากราคาเกินตามที่กระทรวงระบุไว้ จึงต้องส่งเรื่องเข้ากระทรวงทำให้ล่าสุดและไฟตกบ่อยมาก จึงแก้ปัญหาโดยการซื้อแบตมาเปลี่ยนก่อน','',8,'ตรวจสอบ',161,'20',161,'2020-06-15 10:37:46','2020-06-15 04:14:01'),(8752,'2020-06-05','07:30:05',1,8,'1',NULL,7,'2',486,'เครื่องปริ้นคิวปริ้นไม่ได้ เนื่องจากมีฝนตกไฟกระชากทำให้เมนบอร์ดเครื่องปริ้นพังและพอตUSB ซ๊อต',NULL,'ผู้ป่วย,โรงพยาบาล','ได้','ให้ใช้ระบบเดิมไปก่อนไม่ต้องใช้ smart Q','',8,'ตรวจสอบ',161,'20',161,'2020-06-15 10:51:15','2020-06-15 04:13:59'),(8753,'2020-06-12','10:01:15',1,9,'2',1,1,'3',32,'มีผู้รับบริการเข้ามาย้ายสิทธิในห้อง โดยมีเอกสารประจำตัวผู้ป่วยเป็นเอกสารนัดตรวจ CT Scan ที่รพ.ตสม. มีความเสี่ยงเป็นวัณโรค เนื่องจากผู้ป่วยไอติดต่อกันเป็นเวลา 2 เดือน และพึ่งพ้นโทษมาจากสถานพินิจ',NULL,'ผู้ป่วย,ญาติ,เจ้าหน้าที่,อื่นๆ','ได้','ใช้น้ำยาทำความสะอาดฆ่าเชื้อโรคเช็ดโต๊ะ เก้าอี้ ประตู รวมถึงอุปกรณ์เครื่องใช้ต่างๆบริเวณที่ผู้ป่วยมารับบริการ และมีการโทรไปแจ้งประสานกับหน่วยงานที่เกี่ยวข้องให้รับทราบและติดตามอาการของผู้ป่วยแล้ว (งานเวชปฏิบัติ )','',8,'ตรวจสอบ',290,'12',290,'2020-06-15 14:09:22','2020-06-16 03:36:36'),(8754,'2020-04-06','19:58:00',2,8,'1',NULL,7,'2',470,'คนไข้มารับบริการโดยมีสิทธิการรักษาเป็นสิทธิUCนอกเขต ห้องบัตรให้สิทธิเป็นชำระเงินเนื่องจากเรียกเก็บจากรพ.ตสม.ไม่ได้ หลังจากนั้นแพทย์วินิจฉัยให้คนไข้นอนโรงพยาบาล และทำการadmit\r\nห้องบัตรไม่ได้เช็คและเปลี่ยนสิทธิคนไข้ให้เป็นสิทธิประจำตัวเดิม ทำให้คนไข้ใช้สิทธิชำระเงิน ตอนDischargeคนไข้ก็เลยมีค่าใช้จ่าย2876.50บาท ซึ่งคนไข้ก็ยอมจ่าย',NULL,'ผู้ป่วย,ญาติ,อื่นๆ','ได้','แจ้งการเงินทำเรื่องคืนเงินให้ผู้ป่วย','',8,'ตรวจสอบ',284,'11',284,'2020-06-16 10:17:59','2020-06-16 03:22:17'),(8755,'2020-06-18','09:56:45',1,50,'2',11,7,'B',2000002,'เมื่อวันที่15 มิถุนายน เวลา 18.00 น. มีการเปิดบัตรของนายสมศักดิ์ โพธิ แต่HNของผู้ป่วยไม่ถูกต้อง เป็นเลข 000000004 และแพทย์ได้ทำการสั่งเอกซเรย์CXR \r\nวันที่18 มิถุนายน แพทย์เจ้าของไข้ ได้ทำการเปิดดูภาพCXRในระบบPacscแต่ไม่สามารถเปิดดูได้ เพราะห้องบัตรทำการแก้ไข้เลขHNของผู้ป่วยเป็น630001314แล้ว\r\nแต่ในระบบpacsของเอกซเรย์ยังเป็นเลขHNเดิม แพทย์เลยแจ้งมาที่ไอที ไอทีเลยแจ้งมาที่เอกซเรย์ เอกซเรย์เลยทำการเปลี่ยนเลขHNในระบบPacsและทำการส่งภาพเข้าระบบใหม่อีกครั้ง แพทย์จึงสามารถเปิดดูภาพเอกซเรย์ได้',NULL,'อื่นๆ','ได้','เจ้าหน้าที่เอกซเรย์ แจ้งแพทย์เวรว่า สามารถค้นชื่อผู้ป่วยได้ ถ้าค้นHNไม่ได้ เป็นการแก้ปัญหาเฉพาะหน้าก่อน แล้วให้แจ้งเจ้าหน้าที่เอกซเรย์ทราบ\r\nเจ้าหน้าที่เอกซเรย์ ได้แจ้งทางห้องบัตร ให้ทำการตรวจสอบเลขHN หรือข้อมูลของผู้ป่วยให้ถูกต้องทุกครั้ง ถ้ามีการแก้ไขข้อมูลของผู้ป่วย เช่น ชื่อ นามสกุล HN ให้ทำการแจ้งเจ้าหน้าที่เอกซเรย์ทุกครั้ง เพราะเจ้าหน้าที่เอกซเรย์ต้องแก้ไขข้อมูลคนไข้ในระบบpacsให้ตรงกับhosxp','',8,'ตรวจสอบ',253,'7',253,'2020-06-19 10:06:39','2020-06-19 03:07:10'),(8756,'2020-06-22','10:28:50',1,52,'2',2,2,'1',98,'ผป.ชาย 61/1829 เข้าไปสูบบุหรี่ในห้องน้ำชาย ',NULL,'ผู้ป่วย,ญาติ,โรงพยาบาล,อื่นๆ','ได้','แจ้งข้อห้ามในการปฏิบัติตัวเมื่ออยู่ รพ. ซ้ำแก่ผู้ป่วย','',8,'ตรวจสอบ',318,'2',318,'2020-06-22 10:43:04','2020-06-25 09:05:51'),(8757,'2020-06-22','08:30:35',1,47,'2',11,7,'1',470,'นายทรงพล แสนเปา HN 570008825 ได้เปิดวิสิตมาทำฟันที่ห้องทันตกรรม แต่ได้รับการเปิดมา 2 วิสิตที่ห้องทันตกรรม คือ 1.สิทธิกรมบัญชีกลาง 2. สิทธิประกันสังคม ในใบวิสิตเขียนมาเป็นสิทธิกรมบัญชีกลาง ได้เช็คกับห้องบัตรภายหลังว่าไม่มีสิทธิกรมบัญชีกลาง',NULL,'อื่นๆ','ได้','ปิดวิสิตไป 1 วิสิต เหลือวิสิตที่เป็นประกันสังคมไว้','',8,'ตรวจสอบ',163,'9',163,'2020-06-23 08:37:02','2020-06-30 04:50:39'),(8758,'2020-06-05','16:30:05',2,51,'2',19,2,'1',80,'เมื่อวันที่ 5 มิ.ย. 63 เวลา16.30 น. ขณะเติมน้ำดื่มให้ผู้ป่วยพบว่าในถังน้ำดื่มมีลูกน้ำยุงลายจำนวนมากในถัง ',NULL,'ผู้ป่วย,อื่นๆ','ได้','แจ้งให้หัวหน้าเวรรับทราบ และได้เปลี่ยนถังน้ำดื่มก่อนให้ผู้ป่วยบริโภค','',8,'ตรวจสอบ',243,'2',243,'2020-06-24 09:21:08','2020-06-25 08:06:58'),(8759,'2020-06-24','15:13:00',1,51,'1',NULL,2,'2',100,'วันนี้เวลา 14:30 ไปเก็บขยะทั่วไปแทนแม่บ้านที่ประอยู่ พบว่ามีขยะทั่วไปบริเวณด้านหลังของตึกผู้ป่วยใน มีกลิ่นเหม็นเน่าและมีหนอนจำนวนมาก',NULL,'เจ้าหน้าที่,โรงพยาบาล,อื่นๆ','ได้','เก็บไปทิ้งพร้อมล้างถังขยะ\r\nข้อเสนอแนะเพิ่มเติม ควรเก็บทุกวันจะได้ไม่มีหนอนค่ะ','',8,'ตรวจสอบ',329,'19',329,'2020-06-24 15:17:49','2020-07-03 08:39:26'),(8760,'2020-06-15','16:30:00',2,10,'2',4,6,'B',407,'วันที่ 15 มิ.ย. 63 เวลา 16.30 น. มีผู้ช่วยพยาบาลจากห้องฉุกเฉินมาส่งเลือดของนายวันชนะ รื่นสัน ที่ห้อง LAฺB จำนวน 2 tube คือ  หลอดสีแดง 1 หลอด (tube clot blood ) และ  หลอดสีม่วง 1 หลอด (tube EDTA ) ห้อง Lab พบว่าหลอดสีม่วงซึ่งส่งตรวจ CBC  clot (ซึ่งปกติต้องไม่ clot)  และ หลอดสีแดงพบว่าไม่ clot (ปกติต้อง clot)  Lab ได้ตรวจสอบสาเหตุพบว่าหลอดเลือดปิดฝาจุกสลับ tube กัน (ฝาสีแดงปิดหลอดสีม่วง ฝาสีม่วงปิดหลอดสีแดง) ห้อง LAB  จึงปฏิเสธสิ่งส่งตรวจและแจ้งเจ้าหน้าที่ห้องฉุกเฉินเจาะเลือดใหม่ทั้งสองหลอด ',NULL,'ผู้ป่วย','ได้','ปฏิเสธสิ่งส่งตรวจและแจ้งเจ้าหน้าที่ห้องฉุกเฉินเจาะเลือดใหม่ทั้งสองหลอด','',8,'ตรวจสอบ',292,'6',292,'2020-06-25 10:48:18','2020-07-15 07:34:22'),(8761,'2020-06-23','18:19:00',2,51,'1',NULL,5,'B',272,'แพทย์ order cefixime(100 mg) 2*2 oral pc. \r\nในใบ MAR เขียนวิธีใช้เป็น กิน 1 เม็ด วันละ 1 ครั้ง',NULL,'ผู้ป่วย,เจ้าหน้าที่,โรงพยาบาล,อื่นๆ','ได้','แจ้งห้องยา เพื่อแก้ไขข้อมูลให้เป็นไปตาม order แพทย์','',8,'ตรวจสอบ',318,'2',318,'2020-06-25 14:21:46','2020-06-25 08:08:19'),(8762,'2020-06-25','14:24:10',1,17,'2',NULL,2,'2',132,'ขณะที่ได้ทำการซ้อมแผน อุบัติเหตุ หน้ากากพัดลมหลุดร่วงลงมาแตกกระจายเสียงดัง และมีคนไข้อยู่ใกล้บริเวรนั้น',NULL,'อื่นๆ','ได้','วิ่งไปปิดสวิทธ์พัดลมและเก็บเศษใบพัดลม','f496bd0a951ea0c339e1a08e162507dc.jpg',8,'ตรวจสอบ',295,'8',295,'2020-06-25 14:42:23','2020-08-21 07:20:50'),(8763,'2020-06-26','09:05:30',1,7,'2',8,5,'D',258,'580002450 มาทำแผลเมื่อ 25/6/2563 แผลมีหนองรายงานแพทย์ภัทราพรดูแผลให้ตัดไหมและสั่งยาให้ผู้ป่วยกลับไปรับประทานที่บ้าน ผู้ป่วยบอกว่าไปยื่นบัตรที่ห้องยาห้องยาให้กลับบ้านได้ จึงไม่ได้ยากลับไปรับประทาน วันที่ 26/6/2563 ผู้ป่วยกลับมาทำแผลต่อที่รพ.พยาบาลได้สอบถามผู้ป่วยว่าได้ทานยาที่หมอสั่งไหม ผู้ป่วยบอกว่าไม่ได้รับยาตั้งแต่เมื่อวาน ',NULL,'ผู้ป่วย','ได้','แจ้งเภสัชกรวีรพงศ์รับทราบและจ่ายยาให้ผู้ป่วยกลับไปรับประทานที่บ้าน','6e1c4ff8292b4d317c1e83c16c972d51.jpg',3,'ตรวจสอบ',249,'4',249,'2020-06-26 09:18:48','2020-06-26 02:23:18'),(8764,'2020-06-25','14:00:00',1,107,'1',NULL,1,'B',42,'25/6/63 ณ โรงอาหาร บริเวณจัดเตรียมอาหารผู้ป่วยใน : ประมาณ 14.50 น. ช่วงระหว่างกำลังเตรียมอาหารมื้อเย็น นักโภชนาการพบว่าผู้รับจ้างประกอบอาหารวางผ้าขี้ริ้ว วางใกล้ถาดและมีบางส่วนของผ้าขี้ริ้วตกลงในอาหารผู้ป่วย นักโภชนาการจึงแจ้งให้ผู้รับจ้างประกอบอาหารเห็นความเสี่ยงนี้ทันที และขอเปลี่ยนถาดอาหารใหม่ทันที',NULL,'ผู้ป่วย','ได้','นักโภชนาการแจ้งให้ผู้รับจ้างประกอบอาหารเห็นความเสี่ยงนี้ทันที และขอเปลี่ยนถาดอาหารใหม่ทันที','aa45bf4ee0085ffa76a0657832bfdde2.jpg',5,'ตรวจสอบ',267,'15',267,'2020-06-26 13:52:32','2020-06-26 07:00:33'),(8765,'2020-06-26','10:55:00',1,107,'1',NULL,1,'B',42,'25/6/63 ณ โรงอาหาร เวลา 10.55 น. ระหว่างที่นักโภชนาการดูแลการจัดเตรียมอาหารมื้อกลางวัน พบถาดอาหารผู้ป่วยห้องพิเศษมีผงสีดำเปื้อนมือขณะที่จับถาด จึงถามผู้รับจ้างประกอบอาหาร แจ้งว่า ล้างแล้วตากบนชั้นตากภาชนะ พอแห้งแล้วเก็บมาใช้ในมื้อนี้ ',NULL,'อื่นๆ','ได้','1. นักโภชนาการนำเศษฝุ่นผงสีดำที่เปื้อนมือและถาดให้ผู้รับจ้างประกอบอาหารเห็นและแจ้งให้ทราบทันที \r\n2. นักโภชนาการ ติดต่อฝ่ายพัสดุให้ช่วยจัดซื้อผ้าเพื่อคลุมภาชนะที่ตากไว้หลังล้างทำความสะอาดเสร็จ','aa52562507e3c37ca55b5278b88dbebb.jpg',8,'ตรวจสอบ',267,'15',267,'2020-06-26 14:00:11','2020-06-26 07:00:29'),(8766,'2020-06-25','14:14:30',1,23,'2',14,6,'B',292,'แพทย์เวรอีอาร์สั่งเอกซเรย์คนไข้ผิดข้าง ',NULL,'อื่นๆ','ได้','ถามคนไข้ว่าเจ็บข้างไหนแล้วเอกซเรย์ข้างนั้น','',8,'ตรวจสอบ',253,'7',253,'2020-06-26 14:16:51','2020-06-26 07:17:34'),(8767,'2020-06-27','15:06:05',1,23,'2',14,6,'B',292,'แพทย์เวรอีอาร์ สั่งรายการเอกซเรย์ไม่ถูกต้อง ผู้ป่วยเจ็บเท้าขวา แพทย์เขียนสั่งเท้าซ้าย ทั้งในใบIPDและใบvisit',NULL,'อื่นๆ','ได้','เจ้าหน้าที่สอบถามผู้ป่วยก่อนการเอกซเรย์ทำให้รู้ว่าผู้ป่วยเจ็บเท้าขวาไม่ใช่เท้าซ้าย จึงทำการถ่ายเท้าขวา','',8,'ตรวจสอบ',253,'7',253,'2020-06-27 15:08:23','2020-06-27 08:08:54'),(8768,'2020-06-27','08:31:00',1,7,'1',NULL,6,'D',303,'ผุ้ป่วย HN 56/654 มาทำการรักษาด้วย มีอาการหายใจเหนื่อย ไม่ไอ ไม่มีเสมหะ ไม่มีไข้ ไม่มีใจสั่น ไม่มีแน่นหน้าอก พ่นยาเองที่บ้านประมาณ 10 ครั้ง  เวลา 01.39 น. แพทย์ให้  Beradual 2:2 NB x 3 dose  และ Dexa 10 mg IV plan ให้ Admit ผู้ป่วยปฏิเสธ เวลา 08.31 น. ผู้ป่วยกลับมารักษาซ้ำด้วยอาการหายใจเหนื่อย แพทย์ให้พ่นยา Beradual 2:2 NB x 1 dose stat และ ฉีด Dexa 5 mg IV Dx. COPD with AE ยินยอม Admit ',NULL,'ผู้ป่วย','ได้','รักษาตามอาการและอธิบายให้ผู้ป่วยรับทราบเหตุผลของการนอนโรงพยาบาล\r\nรายงานความเสี่ยง','',8,'ตรวจสอบ',248,'4',248,'2020-06-27 16:59:01','2020-06-27 09:59:45'),(8769,'2020-06-11','12:58:00',1,7,'2',14,5,'C',228,'ผู้ป่วย HN 56/1877 มาตรวจด้วยอาการเจ็บหน้าอกและคอ แพทย์ Dx.common cold , spondylosis แพทย์พชราวลีสั่งให้ฉีดยา Tramol 50 mg IV แต่เนื่องจากผู้ป่วยมีประวัติแพ้ยา tramol จึงโทรารายงานแพทย์ แพทย์จึงให้ off ยา tramol \r\n ',NULL,'ผู้ป่วย,ญาติ,เจ้าหน้าที่,โรงพยาบาล,อื่นๆ','ได้','โทรรายงานแพทย์เกี่ยวกับประวัติแพ้ยาของผู้ป่วย \r\nเขียนรายงานความเสี่ยง','',8,'ตรวจสอบ',248,'4',248,'2020-06-27 17:19:03','2020-06-27 10:22:43'),(8770,'2020-06-11','12:58:00',1,7,'2',8,5,'C',228,'ผู้ป่วย HN 56/1877 มาตรวจด้วยอาการเจ็บหน้าอกและคอ แพทย์ Dx.common cold , spondylosis แพทย์พชราวลีสั่งให้ฉีดยา Tramol 50 mg IV ห้องยาสั่งจ่ายยาโดยที่ผู้ป่วยมีประวัติแพ้ยา tramol',NULL,'ผู้ป่วย,ญาติ,เจ้าหน้าที่,โรงพยาบาล,อื่นๆ','ได้','โทรรายงานแพทย์เพื่อ off ยา\r\nรายงานความเสี่ยง','',8,'ตรวจสอบ',248,'4',248,'2020-06-27 17:22:31','2020-06-27 10:22:48'),(8771,'2020-06-27','09:00:00',1,51,'1',NULL,1,'B',20,'ทิ้งขยะของมีคมติดเชื้อของแม่บ้านไว้ที่รถทำความสะอาดของแม่บ้าน โดยไม่นำไปทิ้งในบริเวณที่กำหนด',NULL,'อื่นๆ','ได้','รายงานหัวหน้าเวรรับทราบและรายงานหัวหน้าหน่วยงานรับทราบ','',1,'ตรวจสอบ',317,'4',317,'2020-06-28 01:25:48','2020-07-02 02:42:08'),(8772,'2020-06-29','10:07:10',1,50,'2',2,6,'A',466,'29-06-63 เวลา 08.52 น. นักโภชนาการแจ้งวอร์ดเรื่องรายละเอียดโรคประจำตัวคนไข้ ว่ามีโรคเก๊าต์, ไตระยะ 4, หัวใจ แต่ไม่รู้ชนิดของโรค, Hypothyroid  ผ่านไลน์กลุ่มอาหาร \r\n10.05 น. นักโภชนาการเข้าไปแจ้งทีวอร์ดอีกครั้งและบันทึกรายละเอียดต่าง ๆ ในใบสั่งยอดอาหารให้ ทั้งลงยอดอาหารมื้อกลางวัน ลงประเภทอาหาร ลงอาหรเฉพาะโรคดังกล่าวให้ ดังภาพที่แนบ',NULL,'อื่นๆ','ได้','นักโภชนาการลงบันทึกให้บางส่วน และปรึกษาหัวหน้างานในการหาวิธีแก้ไขร่วมกัน จึงลงความเสี่ยงไว้ก่อน ป้องกันการเกิดความเสี่ยงจริง ในมื้อต่อไป','3ed4b27668b5a5e8ad60dd48e1e7d910.jpg',8,'ตรวจสอบ',267,'15',267,'2020-06-29 10:35:42','2020-06-29 03:36:39'),(8773,'2020-06-29','14:43:00',1,50,'2',2,6,'A',469,'29-06-63 เวลา 14.43 น. นักโภชนาการเข้ามาถามยอดอาหารมื้อเย็นกับ IPD เนื่องจาก 14.30 ยังไม่มีการเคลื่อนไหวยอดการสั่งอาหารมื้อเย็น (ซึ่งโดยทั่วไปมีความจำเป็นต้องเตรียมอาหารล่วงหน้าอย่างน้อย 1 ชั่วโมง) แต่พบว่ายังไม่มีการลงบันทึกยอดสั่งอาหารมื้อเย็นเลย ซึ่งตอนนั้นทางงาน IPD กำลังประชุมเจ้าหน้าที่อยู่จึงเขียนแทนให้ แต่ไม่มีการแจ้งให้ทราบเรื่องการย้ายเตียง/ห้อง รวมถึงการ discharge เพิ่ม ระหว่างช่วงเช้า (d/c ของเตียง 2) และช่วงบ่าย (การย้ายจากเตียงสามัญไปห้องพิเศษ) (นักโภชนาการทราบการเปลี่ยนแปลงดังกล่าวข้างต้นจากการบอกของน้องที่จ่ายอาหารและเดินมาดูว่าเป็นไปตามที่น้องบอกมั๊ย ซึ่งพอมาดูเองก็พบว่าจริง) จึงทำให้มื้อกลางวันส่งอาหารเกินมา 1 คน ซึ่งตรงนี้มีผลอาจทำให้โรงพยาบาลอาจจะต้องจ่ายค่าหัวที่เกินจากการเหมา 10 คน มาจำนวน 1 คน ประมาณ 100 บาทให้กับผู้ประกอบอาหาร \r\nหมายเหตุ : ไม่ได้มีเจตนากล่าวโทษทาง IPD เพียงแต่ต้องการยอดที่ชัดเจนเพราะจะได้เตรียมปริมาณวัตถุดิบให้เพียงพอ หากเพิ่มเติมทีหลังเนื่องจากเราจ้างเหมา เราไม่สามารถบังคับให้เค้า stand by ได้ตลอดเวลา และไม่มีเงื่อนไขบอกเรื่องนี้ในสัญญาจ้างเหมาประกอบอาหาร พอหลังเวลาที่เค้าจ่ายอาหารเสร็จ เค้าอาจจะไปทำธุระที่อื่น หรือฝากคนอื่นมาเฝ้าแทน หรือทำอาหารขายต่อ ทำให้คนไข้ที่เพิ่ง admit ได้อาหารล่าช้าหรืออาจจะไม่ได้ กรณีไม่มีคนอยู่หลังจากเวลาจ่ายอาหาร',NULL,'ผู้ป่วย,เจ้าหน้าที่,โรงพยาบาล,อื่นๆ','ได้','ทำแทน+แจ้งไปในไลน์กลุ่มเรื่องรายละเอียดดังกล่าวและฝากให้ทาง IPD บันทึกในใบยอดการสั่งอาหารด้วย','',5,'ตรวจสอบ',267,'15',267,'2020-06-29 15:26:22','2020-06-29 08:30:43'),(8774,'2020-05-31','12:07:50',1,49,'1',NULL,6,'D',297,'เวลา 12.15 น. ผป. case epilepsy c alcohol withdrawal หลังพยาบาลป้อนอาหารและยาเสร็จ พยบ.ได้ผูกมัด ผป. เนื่องจาก ผป.มีอาการติดสุรา  ผป.นอนหลับพักบนเตียงได้\r\nเวลา 12.30 น. พยบ.ได้ยินเสียงดังคล้ายคนล้ม จึงพบว่าเป็น ผป.case epilepsy c alcohol withdrawal  ล้มอยู่ที่พื้น ผป.มีแผลถลอดมีเลือดซึมที่ริมฝีปาก จำเหตุการณ์ได้',NULL,'ผู้ป่วย,เจ้าหน้าที่,โรงพยาบาล,อื่นๆ','ได้','1.ประเมินอาการผู้ป่วย และรายงานแพทย์\r\n2.สังเกตอาการเปลี่ยนแปลง และเฝ้าระวังความปลอดภัย','',8,'ตรวจสอบ',318,'2',318,'2020-06-30 00:13:41','2020-06-29 17:14:07'),(8775,'2020-06-30','09:20:00',1,50,'2',2,6,'A',466,'30-06-63 เวลา 09.20 น. นักโภชนาการรับยอดการสั่งอาหารมื้อกลางวันจาก IPD ตรวจสอบพบความเสี่ยงหลัก ได้แก่ ไม่ได้ระบุโรคประจำตัวและอาหารเฉพาะโรคที่การจัดบริการอาหารมีผลต่อการพักรักษาตัวของคนไข้ คือ โรคเบาหวาน และไม่ได้เขียนประเภทอาหาร เนื่องจากผู้ป่วยอาจมีเปลี่ยนแปลงประเภทอาหารได้ตามสภาวะการเจ็บป่วย \r\nหมายเหตุ : ไม่ได้มีเจตนากล่าวโทษ เพียงช่วยทวนสอบงานซึ่งกันและกัน และช่วงกันพัฒนาระบบการสั่งอาหารที่ชัเเจนและถูกต้องด้วยกันต่อไป',NULL,'เจ้าหน้าที่,อื่นๆ','ได้','นักโภชนาการแจ้งให้ IPD เขียนบันทึกรายละเอียดเฉพาะโรคของผู้ป่วยลงในใบสั่งอาหารผ่านไลน์ และช่วยตรวจสอบอาหารเฉพาะโรคผู้ป่วยทุกคนในช่วงมื้อกลางวันนี้','53b71237df459b49fba7de1b4ec7ee2f.jpg',5,'ตรวจสอบ',267,'15',267,'2020-06-30 10:27:46','2020-06-30 03:28:17'),(8776,'2020-06-30','10:43:00',1,44,'1',NULL,6,'B',465,'10.43 น. นักโภชนาการแจ้งให้ IPD ช่วยเขียนบันทึกรายละเอียดอาหารเฉพาะโรค แต่นักโภชนาการแจ้งผิดโรคไป 1 คน ปกติคนไข้มีโรคประจำตัว COPD แต่นักโภชนาการไปแจ้งว่า DM HT จึงทำให้จัดอาหารแบบเบาหวานไปให้คนไข้ แต่ไม่ได้เกิดความเสี่ยงหายอะไรต่อผู้ป่วยและโรคที่ผู้ป่วยเป็น',NULL,'เจ้าหน้าที่,อื่นๆ','ได้','กล่าวขอโทษและแจ้งแก้ไขข้อมูลเฉพาะโรคผ่านทางไลน์ IPD เวลา 12.04 น. และแก้ไขในใบสั่งอาหารของฝ่ายโภชนาการ เรียบร้อยแล้ว ','',5,'ตรวจสอบ',267,'15',267,'2020-06-30 12:35:06','2020-06-30 05:35:21'),(8777,'2020-06-30','16:28:15',2,7,'1',NULL,2,'C',131,'เวรบ่าย วันที่ 30/06/63 อุปกรณ์คอมพิวเตอร์ที่ให้สำหรับบันทึกการพยาบาลและลงข้อมูล ใช้งานไม่ได้ จึงต้องส่งซ่อม ในตลอดทั้งเวรนั้น จำเป็นต้องใช้คอมพิวเตอร์ในการทำงาน ทำให้เกิดความไม่สะดวกและล่าช้าต่อการลงบันทึกข้อมูลผู้ป่วย ',NULL,'ผู้ป่วย,โรงพยาบาล','ได้','ติดตามการแจ้งส่งซ่อมและใช้อุปกรณ์คอมพิวเตอร์ที่มีอยู่','',8,'ตรวจสอบ',280,'4',280,'2020-07-01 10:33:43','2020-07-02 02:41:53'),(8778,'2020-07-01','15:01:25',1,78,'2',4,1,'A',29,'พบเข็มเย็บแผลคนไข้ ส่งมาล้างปะปนกับอุปกรณ์เครื่องมือแพทย์ ทำให้เจ้าที่ที่รับผิดชอบล้างของมีความเสี่ยงถูกของมีคมทิ่มตำ',NULL,'เจ้าหน้าที่,อื่นๆ','ได้','ให้อุปกรณ์หนีบจับเข็มแยกออกมาจากเครื่องมือแพทย์, รายงานหัวหน้าฝ่าย','fb9f3cb27beeea2675e8af2206921e26.jpg',8,'ตรวจสอบ',321,'17',321,'2020-07-01 15:08:02','2020-07-01 08:11:24'),(8779,'2020-07-01','13:2