--
-- Table structure for table `riskanalysis`
--

DROP TABLE IF EXISTS `riskanalysis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `riskanalysis` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `risk_code` varchar(50) NOT NULL,
  `risk_title` varchar(255) NOT NULL,
  `risk_description` text DEFAULT NULL,
  `scope_level` varchar(20) NOT NULL DEFAULT 'department',
  `department_id` varchar(10) NOT NULL,
  `program_id` int(11) DEFAULT NULL,
  `category_name` varchar(100) DEFAULT NULL,
  `safety_goal` varchar(255) DEFAULT NULL,
  `essential_std` varchar(255) DEFAULT NULL,
  `risk_owner_name` varchar(255) DEFAULT NULL,
  `is_never_event` tinyint(4) NOT NULL DEFAULT 0,
  `initial_likelihood` tinyint(4) NOT NULL DEFAULT 1,
  `initial_consequence` tinyint(4) NOT NULL DEFAULT 1,
  `initial_risk_score` int(11) NOT NULL DEFAULT 1,
  `initial_risk_level` varchar(20) NOT NULL DEFAULT 'green',
  `risk_prevention` text DEFAULT NULL,
  `risk_transfer` text DEFAULT NULL,
  `risk_monitor` text DEFAULT NULL,
  `risk_mitigation` text DEFAULT NULL,
  `review_frequency_months` int(11) NOT NULL DEFAULT 3,
  `last_reviewed_date` date DEFAULT NULL,
  `next_review_date` date DEFAULT NULL,
  `residual_risk_level` varchar(50) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'open',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `qi_plan` text DEFAULT NULL,
  `source` varchar(100) DEFAULT 'มาตรฐานสำคัญ 9 ด้าน',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

