INSERT INTO `riskanalysis` VALUES (23,'PT/01','การระบุตัวผู้ป่วยผิดพลาด','ความเสี่ยงที่เกิดขึ้นจากการระบุตัวตนของผู้ป่วยผิดพลาดหรือไม่ถูกต้อง ซึ่งอาจส่งผลต่อความปลอดภัยของผู้ป่วยในกระบวนการให้บริการทางการแพทย์ เช่น การให้ยา การรักษา หรือการดำเนินการอื่น ๆ โดยข้อมูลที่ไม่ตรงกับตัวผู้ป่วยจริง','department','1',2,'Clinical Risk (ทางคลินิก)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',1,3,3,9,'yellow','แนวทางการระบุตัวผู้ป่วย',NULL,'รายงานอุบัติการณ์','แนวทางการระบุตัวผู้ป่วย',3,NULL,NULL,NULL,'open','2026-08-03 05:34:08','2026-08-03 05:34:08',NULL,NULL,'มาตรฐานสำคัญ 9 ด้าน'),(24,'EN/16','อัคคีภัย (ไฟไหม้)','ภัยหรือเหตุการณ์อันตรายอันเกิดจากไฟที่ขาดการควบคุมดูแล ทำให้เกิดการติดต่อลุกลามไปตามบริเวณที่มีเชื้อเพลิงเกิดการลุกไหม้ต่อเนื่อง  ส่งผลกระทบต่อความสูญเสียและเสียหายต่อรพ.','department','1',3,'General Risk (ทั่วไป/องค์กร)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',0,3,3,9,'yellow','แนวทางป้องกันอัคคีภัย แผนการระงับเหตุอัคคีภัย',NULL,'รายงานอุบัติการณ์','แนวทางป้องกันอัคคีภัย แผนการระงับเหตุอัคคีภัย',6,NULL,NULL,NULL,'open','2026-08-03 05:34:08','2026-08-03 05:34:08',NULL,NULL,'เรื่องที่หน่วยงานให้ความสำคัญ'),(25,'EN/19','เครื่องมือทั่วไปไม่พร้อมใช้/ไม่เพียงพอ/ชำรุด','การเตรียมเครื่องมือและอุปการณ์ไม่พร้อมใช้ ทั้งเกี่ยวกับการรักษาและไม่เกี่ยวกับการรักษา','department','1',3,'General Risk (ทั่วไป/องค์กร)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',0,3,3,9,'yellow','แนวทางการแจ้งซ่อมออนไลน์',NULL,'รายงานอุบัติการณ์','มีแนวทางปฏิบัติกรณีครุภัณฑ์ชำรุดเสียหาย',6,NULL,NULL,NULL,'open','2026-08-03 05:34:08','2026-08-03 05:34:08',NULL,NULL,'รายงานอุบัติการณ์'),(26,'MI/08','ครุภัณฑ์การแพทย์ชำรุด เสียหาย /สูญหาย','สภาวะที่ครุภัณฑ์การแพทย์หรืออุปกรณ์ที่ใช้ในกระบวนการให้บริการทางการแพทย์ไม่สามารถใช้งานได้ตามปกติ อันเนื่องมาจากการชำรุด การสึกหรอ การเสียหาย หรือการสูญหาย','department','1',8,'General Risk (ทั่วไป/องค์กร)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',0,4,3,12,'orange','มีแนวทางปฏิบัติกรณีครุภัณฑ์ชำรุดเสียหาย',NULL,'รายงานอุบัติการณ์','มีแนวทางปฏิบัติกรณีครุภัณฑ์ชำรุดเสียหาย',3,NULL,NULL,NULL,'open','2026-08-03 05:34:08','2026-08-03 05:34:08',NULL,NULL,'รายงานอุบัติการณ์'),(27,'PT/02','ผู้ป่วยพลัดตกหกล้ม','การเปลี่ยนตำแหน่งของร่างกายจากการลื่นไถล ถลา หรือตกไปสู่พื้นผิวที่ต่ำกว่า\nซึ่งเป็นเหตุการณ์ที่เกิดขึ้นโดยไม่ได้ตั้งใจและไม่สามารถควบคุมได้ อาจส่งผลให้ร่างกายของผู้ป่วยได้รับบาดเจ็บ หรือ\nไม่ได้รับบาดเจ็บก็ตาม','department','1',2,'Clinical Risk (ทางคลินิก)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',0,3,3,9,'yellow','1. แนวทางป้องกันผู้ป่วยพลัดตกเตียง                                         2. เกิดแนวทางการดูแลสังเกตอาการผู้ป่วยหลังฉีดยา',NULL,'รายงานอุุบัติการณ์','แนวทางป้องกันผู้ป่วยพลัดตกเตียง',6,NULL,NULL,NULL,'open','2026-08-03 05:34:08','2026-08-03 05:34:08',NULL,NULL,'รายงานอุบัติการณ์'),(28,'PT/01','การระบุตัวผู้ป่วยผิดพลาด','ความเสี่ยงที่เกิดขึ้นจากการระบุตัวตนของผู้ป่วยผิดพลาดหรือไม่ถูกต้อง ซึ่งอาจส่งผลต่อความปลอดภัยของผู้ป่วยในกระบวนการให้บริการทางการแพทย์ เช่น การให้ยา การรักษา หรือการดำเนินการอื่น ๆ โดยข้อมูลที่ไม่ตรงกับตัวผู้ป่วยจริง','department','2',2,'Clinical Risk (ทางคลินิก)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',1,3,3,9,'yellow','แนวทางการระบุตัวผู้ป่วย',NULL,'รายงานอุบัติการณ์','แนวทางการระบุตัวผู้ป่วย',3,NULL,NULL,NULL,'open','2026-08-03 05:34:08','2026-08-03 05:34:08',NULL,NULL,'มาตรฐานสำคัญ 9 ด้าน'),(29,'EN/16','อัคคีภัย (ไฟไหม้)','ภัยหรือเหตุการณ์อันตรายอันเกิดจากไฟที่ขาดการควบคุมดูแล ทำให้เกิดการติดต่อลุกลามไปตามบริเวณที่มีเชื้อเพลิงเกิดการลุกไหม้ต่อเนื่อง  ส่งผลกระทบต่อความสูญเสียและเสียหายต่อรพ.','department','2',3,'General Risk (ทั่วไป/องค์กร)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์',0,3,3,9,'yellow','แนวทางป้องกันอัคคีภัย แผนการระงับเหตุอัคคีภัย',NULL,'รายงานอุบัติการณ์','แนวทางป้องกันอัคคีภัย แผนการระงับเหตุอัคคีภัย',6,NULL,NULL,NULL,'open','2026-08-03 05:34:09','2026-08-03 05:34:09',NULL,NULL,'เรื่องที่หน่วยงานให้ความสำคัญ'),(30,'EN/19','เครื่องมือทั่วไปไม่พร้อมใช้/ไม่เพียงพอ/ชำรุด','การเตรียมเครื่องมือและอุปการณ์ไม่พร้อมใช้ ทั้งเกี่ยวกับการรักษาและไม่เกี่ยวกับการรักษา','department','2',3,'General Risk (ทั่วไป/องค์กร)',NULL,NULL,'ณัฐนันท์ อมรพีรสิทธิ์'