  `current_risk_score` int(11) NOT NULL DEFAULT 1,
  `current_risk_level` varchar(20) NOT NULL DEFAULT 'green',
  `updated_prevention` text DEFAULT NULL,
  `is_escalated` tinyint(4) NOT NULL DEFAULT 0,
  `escalation_target` varchar(100) DEFAULT NULL,
  `reviewed_by` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_risk_analysis_id` (`risk_analysis_id`),
  CONSTRAINT `riskanalysis_review_risk_analysis_id_fkey` FOREIGN KEY (`risk_analysis_id`) REFERENCES `riskanalysis` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
