DROP TABLE IF EXISTS `riskregister`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `riskregister` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ID_Riskregister',
  `id_risk` int(11) NOT NULL DEFAULT 0 COMMENT 'ID_Risk',
  `date_report` date NOT NULL COMMENT 'วันรายงาน',
  `time_report` time NOT NULL COMMENT 'เวลารายงาน',
  `duration_id` int(11) DEFAULT NULL COMMENT 'เวรที่เกิด',
  `location_id` int(11) DEFAULT NULL COMMENT 'สถานที่เกิดความเสี่ยง',
  `user_ir_type` varchar(50) NOT NULL COMMENT 'ประเภทการรายงาน',
  `user_ir` int(11) DEFAULT NULL COMMENT 'แผนกที่รายงานถึง',
  `program_id` int(11) DEFAULT NULL COMMENT 'โปรแกรมความเสี่ยง',
  `level_id` varchar(2) NOT NULL COMMENT 'ระดับความรุนแรง',
  `riskstore_id` int(11) DEFAULT NULL,
  `detail` text DEFAULT NULL COMMENT 'เหตุการ/รายละเอียดเพิ่มเติม',
  `detail_hosxp` text DEFAULT NULL COMMENT 'รายละเอียดข้อมูลคนไข้',
  `affected` varchar(50) DEFAULT NULL COMMENT 'ผู้เสียหาย/ได้รับผลกระทบ',
  `edit` varchar(10) DEFAULT NULL COMMENT 'การแก้ปัญหา',
  `problem_basic` text DEFAULT NULL COMMENT 'วิธีแก้ปัญหาเบื้องต้น',
  `image` text DEFAULT NULL COMMENT 'เอกสาร-ภาพประกอบ',
  `inform_id` int(11) NOT NULL COMMENT 'ที่มาของรายงานความเสี่ยง',
  `status_risk` varchar(100) DEFAULT NULL COMMENT 'สถานะความเสี่ยง',
  `created_by` int(11) DEFAULT NULL COMMENT 'บันทึกโดย',
  `department_id` varchar(3) NOT NULL COMMENT 'สังกัดแผนก',
  `updated_by` int(11) DEFAULT NULL COMMENT 'อับเดทโดย',
  `create_date` datetime DEFAULT NULL COMMENT 'วันบันทึก',
  `modify_date` timestamp NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE current_timestamp() COMMENT 'วันปรับปรุง',
  `send_date` datetime DEFAULT NULL COMMENT 'วันที่นำเข้าข้อมูล',
  `send_use` varchar(150) DEFAULT NULL COMMENT 'ผู้ลงทะเบียน',
  `register_date` date NOT NULL COMMENT 'วันที่ตรวจสอบ',
  `note` varchar(255) DEFAULT NULL COMMENT 'Note',
  `refer_type` varchar(1) DEFAULT NULL COMMENT 'การส่งต่อ',
  `sendto_team_id` int(11) DEFAULT NULL COMMENT 'ส่งให้ทีม',
  `sendto_department_id` varchar(3) DEFAULT NULL COMMENT 'ส่งให้แผนก',
  `sendto_member_cid` varchar(13) DEFAULT NULL COMMENT 'ส่งให้ผู้รับผิดชอบ',
  `repeat_code` varchar(3) DEFAULT NULL COMMENT 'รหัสการทบทวน',
  `link_key` varchar(100) DEFAULT NULL COMMENT 'รหัสลิงค์สำหรับไลน์',
  `url` text DEFAULT NULL COMMENT 'ลิงค์',
  `is_sec41` tinyint(1) DEFAULT 0,
  `is_potential_harm` tinyint(1) DEFAULT 0,
  `rca_required` tinyint(1) DEFAULT 0,
  `rca_criteria_match` varchar(100) DEFAULT NULL,
  `rca_status` varchar(50) DEFAULT 'NONE',
  `rca_case_id` varchar(50) DEFAULT NULL,
  `nrls_code` varchar(50) DEFAULT NULL,
  `nrls_name_snapshot` text DEFAULT NULL,
  `classification_status` varchar(20) DEFAULT 'PENDING',
  `classified_by` int(11) DEFAULT NULL,
  `classified_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`,`id_risk`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=13561 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;
