--
-- Table structure for table `riskreview`
--

DROP TABLE IF EXISTS `riskreview`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `riskreview` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `risk_id` int(11) DEFAULT NULL COMMENT 'เลขความเสี่ยง',
  `riskregister_id` int(11) DEFAULT NULL COMMENT 'เลขทะเบียนความเสี่ยง',
  `riskvisit` varchar(14) NOT NULL COMMENT 'เลขทบทวน',
  `review_date` date NOT NULL COMMENT 'วันที่ทบทวน',
  `review_time` time DEFAULT NULL COMMENT 'เวลา',
  `token_upload` varchar(100) DEFAULT NULL COMMENT 'token_upload',
  `files` text DEFAULT NULL COMMENT 'เอกสารแนบ',
  `hits` int(11) DEFAULT NULL,
  `cause_problem` varchar(255) DEFAULT NULL COMMENT 'สาเหตุของปัญาหา',
  `notereview` text NOT NULL COMMENT 'บันทึกการทบทวน',
  `reviewresults_id` int(11) NOT NULL COMMENT 'ผลการทวบทวน',
  `review_cid` text DEFAULT NULL COMMENT 'ผู้ร่วมทบทวน',
  `repeat` varchar(1) DEFAULT NULL COMMENT 'ทบทวนซ้ำ',
  `discharge` varchar(1) DEFAULT NULL COMMENT 'จำหน่าย',
  `status_risk` varchar(100) DEFAULT 'ทบทวน' COMMENT 'สถานะความเสี่ยง',
  `count` int(11) DEFAULT NULL COMMENT 'จำนวนทบทวน',
  `created_by` int(11) DEFAULT NULL COMMENT 'บันทึกโดย',
  `updated_by` int(11) DEFAULT NULL COMMENT 'อับเดทโดย',
  `create_date` datetime DEFAULT NULL COMMENT 'วันบันทึก',
  `modify_date` timestamp NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE current_timestamp() COMMENT 'วันปรับปรุง',
  PRIMARY KEY (`id`,`riskvisit`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=6100 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

