DROP TABLE IF EXISTS `risks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `risks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `no` int(11) DEFAULT NULL,
  `RRID` int(11) DEFAULT NULL,
  `RID` int(11) DEFAULT NULL,
  `risk_date` date DEFAULT NULL,
  `risk_time` varchar(10) DEFAULT NULL,
  `send_date` datetime DEFAULT NULL,
  `user_ir_type` varchar(50) DEFAULT NULL,
  `dept_from` varchar(100) DEFAULT NULL,
  `dept_to` varchar(100) DEFAULT NULL,
  `riskstore` text DEFAULT NULL,
  `level` varchar(5) DEFAULT NULL,
  `problem_basic` text DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `detail` text DEFAULT NULL,
  `review` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_risk_date` (`risk_date`) USING BTREE,
  KEY `idx_rrid` (`RRID`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4862 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=COMPACT;
