DROP TABLE IF EXISTS `riskstore`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `riskstore` (
  `riskstore_id` int(11) NOT NULL AUTO_INCREMENT,
  `riskstore_name` varchar(200) NOT NULL COMMENT 'ชื่อความเสี่ยง',
  `inform_id` int(11) DEFAULT NULL COMMENT 'ที่มาของความเสี่ยง',
  `type_id` int(11) DEFAULT NULL COMMENT 'ประเภทความเสี่ยง',
  `program_id` int(11) DEFAULT NULL COMMENT 'โปรแกรมความเสี่ยง',
  `level_id` int(11) DEFAULT NULL COMMENT 'ระดับความรุนแรง',
  `group_id` int(11) DEFAULT NULL COMMENT 'กลุ่มความเสี่ยง',
  `team_id` int(11) DEFAULT NULL COMMENT 'ทีม',
  `member_cid` varchar(13) DEFAULT NULL COMMENT 'ผู้รับผิดชอบความเสี่ยง',
  `status` varchar(1) DEFAULT NULL COMMENT 'สถานะ',
  `create_date` datetime DEFAULT NULL COMMENT 'วันบันทึก',
  `modify_date` timestamp NULL DEFAULT NULL COMMENT 'วันปรับปรุง',
  `created_by` int(11) DEFAULT NULL COMMENT 'บันทึกโดย',
  `updated_by` int(11) DEFAULT NULL COMMENT 'อับเดทโดย',
  `nrls_code` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`riskstore_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2000073 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

